CREATE OR REPLACE VIEW reporting.vw_ecu_health AS SELECT r.sw_i_step,d.ecu_name,COUNT(*) dtc_count,COUNT(DISTINCT d.dtc_code) unique_dtc_count,COUNT(*) FILTER(WHERE d.status='Active') active_dtc_count,SUM(d.occurrence_counter) total_occurrences,ROUND(AVG(d.risk_score),2) average_risk,MAX(d.risk_score) maximum_risk FROM raw.dtc_event d JOIN raw.diagnostic_report r ON r.report_id=d.report_id GROUP BY r.sw_i_step,d.ecu_name;
CREATE OR REPLACE VIEW reporting.vw_release_summary AS SELECT r.sw_i_step,COUNT(DISTINCT r.file_id) report_count,COUNT(*) dtc_count,COUNT(DISTINCT d.dtc_code) unique_dtc_count,COUNT(*) FILTER(WHERE d.status='Active') active_dtc_count,SUM(d.occurrence_counter) total_occurrences,ROUND(COUNT(*)::NUMERIC/NULLIF(COUNT(DISTINCT r.file_id),0),2) dtcs_per_report FROM raw.diagnostic_report r JOIN raw.dtc_event d ON d.report_id=r.report_id GROUP BY r.sw_i_step;
CREATE OR REPLACE VIEW reporting.vw_data_quality AS SELECT p.process_run_id,p.file_id,p.process_name,p.start_time,p.end_time,p.process_status,COUNT(q.quality_issue_id) total_issues,COUNT(q.quality_issue_id) FILTER(WHERE q.severity='Error') error_count,COUNT(q.quality_issue_id) FILTER(WHERE q.severity='Critical') critical_count,CASE WHEN COUNT(q.quality_issue_id) FILTER(WHERE q.severity IN('Error','Critical'))=0 THEN 100 ELSE 0 END quality_score FROM admin.process_execution_log p LEFT JOIN admin.data_quality_issue q ON q.process_run_id=p.process_run_id GROUP BY p.process_run_id,p.file_id,p.process_name,p.start_time,p.end_time,p.process_status;
